Import ListNotations.
Open Scope bv_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Notation rsegs := Asan_loaded_segments (only parsing).

Definition sub_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (lo : Z) (m : word -> option byte) (rlo rhi : Z) : machine_state -> Prop :=
  fun ms' => exists t0' t1' t2' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' m',
    ms' = MS (mkR ra sp gp tp t0' t1' t2' s0 s1 (Z_to_bv 64 rlo) (Z_to_bv 64 rhi) a2' a3' a4' a5' a6' a7'
                  s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3' t4' t5' t6') F (ret_pc ra) fc None m' (seg_rom rsegs)
    /\ munch [(bv_unsigned sp + -48, bv_unsigned sp)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp).

(* [comment removed for export] *)
Theorem sub_walk_zero : forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
   (F : bvmap 5 word) fc m (lo : Z) (Na Ea : Z),
  stk rsegs m lo (bv_unsigned sp) -> mem_inv rsegs m -> (lo <= bv_unsigned sp - 48)%Z ->
  qok Na Ea -> bv_unsigned a0 = lo64 (qenc Na Ea) -> bv_unsigned a1 = hi64 (qenc Na Ea) ->
