Lemma shl_or_shr Dhi Dlo sh : 0 <= Dhi < 2 ^ 64 -> 0 <= Dlo < 2 ^ 64 -> 1 <= sh <= 63 ->
  Z.lor (Z.land (Z.shiftl Dhi sh) 18446744073709551615) (Z.land (Z.shiftr (Z.shiftr Dlo 1) (63 - sh)) 18446744073709551615)
  = (Dhi mod 2 ^ (64 - sh)) * 2 ^ sh + Dlo / 2 ^ (64 - sh).
Proof.
