  (0 < x < 2 ^ 64)%Z -> (0 <= f <= 1)%Z -> (0 <= Dhi < 2 ^ 64)%Z -> (0 <= Dlo < 2 ^ 64)%Z -> (0 <= ahi < 2 ^ 63)%Z ->
  (113 <= e <= 32766)%Z -> (13 <= 63 - Z.log2 x + 64 * f <= 75)%Z ->
  let sh := (51 - Z.log2 x + f * 64)%Z in
  let hi := ((Dhi mod 2 ^ (64 - sh)) * 2 ^ sh + Dlo / 2 ^ (64 - sh))%Z in
  let lw := ((Dlo * 2 ^ sh) mod 2 ^ 64)%Z in
