                  (Z_to_bv 64 (e * 281474976710656 + hb + 9223372036854775808)) (Z_to_bv 64 lb)
                  (Z_to_bv 64 la) (Z_to_bv 64 (e * 281474976710656 + ha)) (Z_to_bv 64 (-1)) (Z_to_bv 64 281474976710655)
