Lemma sub_norm_ok N Dhi Dlo x f :
  2 ^ 49 <= N < 2 ^ 112 -> 0 <= Dhi -> 0 <= Dlo < 2 ^ 64 -> Dhi * 2 ^ 64 + Dlo = 8 * N ->
  (f = 0 /\ x = Dhi /\ Dhi <> 0) \/ (f = 1 /\ x = Dlo /\ Dhi = 0) ->
  let sh := 51 - Z.log2 x + f * 64 in
  let hi := (Dhi mod 2 ^ (64 - sh)) * 2 ^ sh + Dlo / 2 ^ (64 - sh) in
  let lw := (Dlo * 2 ^ sh) mod 2 ^ 64 in
  0 < x < 2 ^ 64 /\ 13 <= 63 - Z.log2 x + 64 * f <= 75 /\ 2 ^ 51 <= hi < 2 ^ 52 /\ lw mod 8 = 0 /\
  lw / 8 + (hi mod 8) * 2 ^ 61 = qS N mod 2 ^ 64 /\ sh = 112 - Z.log2 N /\ hi / 8 = qS N / 2 ^ 64.
