Lemma sig3_diff ha la hb lb : 0 <= ha < 2 ^ 48 -> 0 <= la < 2 ^ 64 -> 0 <= hb < 2 ^ 48 -> 0 <= lb < 2 ^ 64 ->
  (8 * ha + la / 2 ^ 61 + 2 ^ 51) * 2 ^ 64 + (la * 8) mod 2 ^ 64 - ((8 * hb + lb / 2 ^ 61 + 2 ^ 51) * 2 ^ 64 + (lb * 8) mod 2 ^ 64)
